class Solution {
public:
    int widestPairOfIndices(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> seen;
        seen[0] = -1;
        int curr = 0, maxWidth = 0;
        for (int i = 0; i < (int)nums1.size(); i++) {
            curr += nums1[i] - nums2[i];
            if (seen.count(curr)) {
                maxWidth = max(maxWidth, i - seen[curr]);
            } else {
                seen[curr] = i;
            }
        }
        return maxWidth;
    }
