import java.util.*;

class Solution {
    public int widestPairOfIndices(int[] nums1, int[] nums2) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, -1);
        int curr = 0, maxWidth = 0;
        for (int i = 0; i < nums1.length; i++) {
            curr += nums1[i] - nums2[i];
            if (seen.containsKey(curr)) {
                maxWidth = Math.max(maxWidth, i - seen.get(curr));
            } else {
                seen.put(curr, i);
            }
        }
        return maxWidth;
    }
}

var widestPairOfIndices = function(nums1, nums2) {
  const seen = new Map();
  seen.set(0, -1);
  let curr = 0, maxWidth = 0;
  for (let i = 0; i < nums1.length; i++) {
    curr += nums1[i] - nums2[i];
    if (seen.has(curr)) {
      maxWidth = Math.max(maxWidth, i - seen.get(curr));
    } else {
      seen.set(curr, i);
    }
  }
  return maxWidth;
};
